package credentials

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"sync"
	"testing"
)

// DEVDESK-610: the static guard that keeps the host secret store behind the
// HostStore seam (hoststore.go). The runtime guard (refuseUnderTest) only sees
// the code paths a test executes; this one reads every .go file of the module
// (go/parser, no type information) and reports three ways the isolation can be
// bypassed or leak into production:
//
//	K1  an import of github.com/zalando/go-keyring outside internal/credentials/hoststore.go
//	    and the _test.go files of internal/credentials. A test elsewhere that talks to
//	    go-keyring (mock or not) bypasses the seam and the fake.
//	K2  a reference to credentials.SwapHostStoreForTest in a non-test file, except
//	    internal/testutil/fakekeyring and internal/credentials itself. The seam is for
//	    tests; production code must never replace the host store.
//	K3  an import of internal/testutil/fakekeyring from a non-test file (it imports
//	    "testing" and must not reach a production binary). No exception.
//
// What the guard cannot see (a shadowed package name, an import path built at
// run time, a test that shells out to a binary that reaches the keyring) is
// listed in docs/architecture/configuration.md.

const (
	ruleKeyringImport = "K1"
	ruleSwapInProd    = "K2"
	ruleFakeInProd    = "K3"

	goKeyringPath    = "github.com/zalando/go-keyring"
	credentialsPath  = "github.com/anthnel/devdesk/internal/credentials"
	fakeKeyringPath  = "github.com/anthnel/devdesk/internal/testutil/fakekeyring"
	swapSeamName     = "SwapHostStoreForTest"
	credentialsDir   = "internal/credentials"
	hostStoreFile    = "internal/credentials/hoststore.go"
	fakeKeyringDir   = "internal/testutil/fakekeyring"
	hostGuardMinimum = 50
)

var hostStoreRules = []string{ruleKeyringImport, ruleSwapInProd, ruleFakeInProd}

// hostStoreExcludedDirs are skipped at any depth below the module root, like the
// other source guards.
var hostStoreExcludedDirs = []string{".worktrees", ".git", "vendor", "testdata", "docs-site", "node_modules"}

// hostViolation is one place where the host secret store is reached or the seam
// is used outside what the rules allow.
type hostViolation struct {
	File string // slash path from the module root
	Line int
	Rule string // "K1".."K3"
}

// String is the report line: file:line: rule, then what to do.
func (v hostViolation) String() string {
	return fmt.Sprintf("%s:%d: %s %s", v.File, v.Line, v.Rule, hostStoreAdvice[v.Rule])
}

// hostStoreAdvice names the rule broken and the way out, so a failure needs no
// trip to the documentation.
var hostStoreAdvice = map[string]string{
	ruleKeyringImport: "imports github.com/zalando/go-keyring outside internal/credentials; " +
		"isolate with fakekeyring.Install() or fakekeyring.Fresh(t) and go through credentials (DEVDESK-610)",
	ruleSwapInProd: "calls credentials.SwapHostStoreForTest from a non-test file; " +
		"the seam is for _test.go files and internal/testutil/fakekeyring only (DEVDESK-610)",
	ruleFakeInProd: "imports internal/testutil/fakekeyring from a non-test file; " +
		"it imports \"testing\" and belongs to _test.go files only (DEVDESK-610)",
}

// importLocalName is the identifier an import binds in the file: its alias, or
// the last element of its path. "_" and "." are returned as is.
func importLocalName(spec *ast.ImportSpec, importPath string) string {
	if spec.Name != nil {
		return spec.Name.Name
	}
	return path.Base(importPath)
}

// scanHostStoreSource parses src as the file name (a slash path from the module
// root) and returns its violations ordered by line, then rule.
func scanHostStoreSource(name string, src []byte) ([]hostViolation, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
	if err != nil {
		return nil, err
	}
	isTest := strings.HasSuffix(name, "_test.go")
	dir := path.Dir(name)

	var out []hostViolation
	add := func(pos token.Pos, rule string) {
		out = append(out, hostViolation{File: name, Line: fset.Position(pos).Line, Rule: rule})
	}

	credName := ""   // local name of internal/credentials ("" = not imported)
	credDot := false // internal/credentials is dot-imported
	for _, spec := range f.Imports {
		p, err := strconv.Unquote(spec.Path.Value)
		if err != nil {
			continue
		}
		switch p {
		case goKeyringPath:
			if name != hostStoreFile && (!isTest || dir != credentialsDir) {
				add(spec.Pos(), ruleKeyringImport)
			}
		case fakeKeyringPath:
			if !isTest {
				add(spec.Pos(), ruleFakeInProd)
			}
		case credentialsPath:
			credName = importLocalName(spec, p)
			credDot = credName == "."
		}
	}

	swapAllowed := isTest || dir == fakeKeyringDir || dir == credentialsDir
	if credName != "" && !swapAllowed {
		ast.Inspect(f, func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.SelectorExpr:
				if id, ok := n.X.(*ast.Ident); ok && !credDot && id.Name == credName && n.Sel.Name == swapSeamName {
					add(n.Sel.Pos(), ruleSwapInProd)
				}
			case *ast.Ident:
				if credDot && n.Name == swapSeamName {
					add(n.Pos(), ruleSwapInProd)
	if hostGuardFiles < hostGuardMinimum {
		t.Fatalf("the host store guard read %d files under %s, want the whole module", hostGuardFiles, hostGuardRoot)
	}
	return hostGuardRoot, hostGuardViolations
}

// The real module follows K1 to K3: no test outside internal/credentials talks
// to go-keyring, nothing in production replaces the store or imports the fake.
func TestHostStoreGuardWalk(t *testing.T) {
	_, vs := scanHostStoreRepo(t)
	for _, v := range vs {
		t.Error(v.String())
	}
}

// hostGuardCase is one synthetic source and the violations expected, each as
// "line rule".
type hostGuardCase struct {
	name string
	file string
	src  string
	want []string
}

// Each rule is exercised on synthetic sources: a violation is reported with its
// rule, and the allowed uses are not. A rule dropped from the detector would
// fail here while the real-module test stays green.
func TestHostStoreGuardDetectors(t *testing.T) {
	cases := []hostGuardCase{
		// K1
		{
			name: "K1: a test outside credentials imports go-keyring",
			file: "internal/app/x_test.go",
			src: `package app
import "github.com/zalando/go-keyring"
var _ = keyring.MockInit
`,
			want: []string{"2 K1"},
		},
		{
			name: "K1: a production file outside credentials imports go-keyring",
			file: "internal/other/x.go",
			src: `package other
import "github.com/zalando/go-keyring"
var _ = keyring.Get
`,
			want: []string{"2 K1"},
		},
		{
			name: "K1: an aliased import",
			file: "internal/app/x_test.go",
			src: `package app
import kr "github.com/zalando/go-keyring"
var _ = kr.MockInit
`,
			want: []string{"2 K1"},
		},
		{
			name: "K1: a blank import",
			file: "cmd/tool/main.go",
			src: `package main
import _ "github.com/zalando/go-keyring"
func main() {}
`,
			want: []string{"2 K1"},
		},
		{
			name: "K1: a dot import",
			file: "internal/ui/setup/x_test.go",
			src: `package setup
import . "github.com/zalando/go-keyring"
`,
			want: []string{"2 K1"},
		},
		{
			name: "K1: a grouped import is found at its own line",
			file: "internal/app/x_test.go",
			src: `package app
import (
	"testing"

	"github.com/zalando/go-keyring"
)
var _ testing.TB
var _ = keyring.MockInit
`,
			want: []string{"5 K1"},
		},
		{
			name: "K1: a subpackage of credentials is not credentials",
			file: "internal/credentials/sub/x_test.go",
			src: `package sub
import "github.com/zalando/go-keyring"
`,
			want: []string{"2 K1"},

package ociresources

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"testing"

	tea "charm.land/bubbletea/v2"
)

// The commands in commands.go shell out to docker and, for a scan, to trivy.
// Rather than stub the seam inside internal/docker — which is unexported, and
// stubbing it would leave the wrapper's own error handling untested — the tools
// are installed on a PATH of the test's own making. Each one is a copy of the
// test binary, which TestMain teaches to behave as the tool: what it prints and
// what it exits with come from the environment.
//
// This is the technique internal/scan uses (dependencies_test.go), with one
// addition: a single fake answers several different commands here — `docker
// image ls` and `docker network inspect` reach the same file — so the response
// is selected by the invocation rather than fixed for the whole process.

const (
	helperMode   = "DEVDESK_OCI_HELPER"
	helperScript = "DEVDESK_OCI_HELPER_SCRIPT"
	// helperLog names a file each invocation is appended to, so a test can
	// assert what the tool was actually asked to do. The fake runs in its own
	// process, so a file is the only channel that does not collide with the
	// output the caller is parsing.
	helperLog = "DEVDESK_OCI_HELPER_LOG"
)

// fakeReply is what a fake tool does for one invocation.
type fakeReply struct {
	Stdout string `json:"stdout"`
	Stderr string `json:"stderr"`
	Exit   int    `json:"exit"`
}

// fakeScript maps an invocation prefix — the tool name followed by the leading
// arguments, e.g. "docker image ls" — to the reply it produces. The longest
// matching prefix wins, so "docker image ls" and "docker image inspect" can be
// scripted separately. An invocation nothing matches succeeds silently, which
// is how "docker accepted the command and printed nothing" is expressed.
type fakeScript map[string]fakeReply

// runAsHelper is the whole of the fake tool. It runs in a subprocess, so it
// reports through its exit code and streams rather than through testing.T.
func runAsHelper() int {
	var script fakeScript
	if raw := os.Getenv(helperScript); raw != "" {
		if err := json.Unmarshal([]byte(raw), &script); err != nil {
			_, _ = fmt.Fprintf(os.Stderr, "unreadable helper script: %v\n", err)
			return 127
		}
	}

	name := strings.TrimSuffix(filepath.Base(os.Args[0]), ".exe")
	invocation := strings.Join(append([]string{name}, os.Args[1:]...), " ")

	if path := os.Getenv(helperLog); path != "" {
		f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
		if err != nil {
			_, _ = fmt.Fprintf(os.Stderr, "cannot log the invocation: %v\n", err)
			return 127
		}
		_, _ = fmt.Fprintln(f, invocation)
		_ = f.Close()
	}

	var match string
	for prefix := range script {
		if strings.HasPrefix(invocation, prefix) && len(prefix) > len(match) {
			match = prefix
		}
	}
	reply := script[match]

	if reply.Stdout != "" {
		_, _ = fmt.Fprint(os.Stdout, reply.Stdout)
	}
	if reply.Stderr != "" {
		_, _ = fmt.Fprint(os.Stderr, reply.Stderr)
	}
	return reply.Exit
}

// fakeToolDir holds one copy of the test binary per tool name. Copying is the
// expensive part — the binary is tens of megabytes — and what a fake *does*
// comes from the environment, so the copies are made once and shared. Nothing
// in this package runs in parallel, but the mutex keeps that from being a
// silent requirement.
var (
	fakeToolMu  sync.Mutex
	fakeToolDir string
)

// installFakeTools puts the named tools on an otherwise empty PATH and scripts
// how they answer.
func installFakeTools(t *testing.T, script fakeScript, names ...string) {
	t.Helper()

	dir := ensureFakeTools(t, names...)

	encoded, err := json.Marshal(script)
	if err != nil {
		t.Fatalf("encoding the helper script: %v", err)
	}
	t.Setenv("PATH", dir)
	t.Setenv(helperMode, "1")
	t.Setenv(helperScript, string(encoded))
}

// installFakeDocker is the common case: docker alone, answering one script.
func installFakeDocker(t *testing.T, script fakeScript) {
	t.Helper()
	installFakeTools(t, script, "docker")
}

// recordInvocations makes the installed fakes append what they were asked to a
// file, and returns a reader for it.
func recordInvocations(t *testing.T) func() []string {
	t.Helper()

	path := filepath.Join(t.TempDir(), "invocations")
	t.Setenv(helperLog, path)

	return func() []string {
		body, err := os.ReadFile(path)
		if err != nil {
			return nil
		}
		var lines []string
		for _, line := range strings.Split(strings.TrimSpace(string(body)), "\n") {
			if line != "" {
				lines = append(lines, line)
			}
		}
		return lines
	}
}

// noDocker points PATH at a directory holding nothing, which is what an
// uninstalled docker looks like to exec.LookPath.
func noDocker(t *testing.T) {
	t.Helper()
	t.Setenv("PATH", t.TempDir())
}

func ensureFakeTools(t *testing.T, names ...string) string {
	t.Helper()

	fakeToolMu.Lock()
	defer fakeToolMu.Unlock()

	if fakeToolDir == "" {
		dir, err := os.MkdirTemp("", "devdesk-oci-tools")
		if err != nil {
			t.Fatalf("creating the tool directory: %v", err)
		}
		fakeToolDir = dir
	}

	for _, name := range names {
		if runtime.GOOS == "windows" {
			name += ".exe"
		}
		path := filepath.Join(fakeToolDir, name)
		if _, err := os.Stat(path); err == nil {
			continue
		}
		self, err := os.Executable()
		if err != nil {
			t.Fatalf("locating the test binary: %v", err)
		}
		body, err := os.ReadFile(self)
		if err != nil {
			t.Fatalf("reading the test binary: %v", err)
		}
		if err := os.WriteFile(path, body, 0o755); err != nil {
			t.Fatalf("installing %s: %v", name, err)
		}
	}
	return fakeToolDir
}

// removeFakeTools is called by TestMain once the suite is over.
func removeFakeTools() {
	fakeToolMu.Lock()
	defer fakeToolMu.Unlock()
	if fakeToolDir != "" {
		_ = os.RemoveAll(fakeToolDir)
		fakeToolDir = ""
	}
}

// run executes a command and returns the single message it produced. tea.Cmd is
// a function returning a message, so this is what the Bubble Tea runtime does
// with it.
func run(t *testing.T, cmd tea.Cmd) tea.Msg {
	t.Helper()
	if cmd == nil {
		t.Fatal("no command to run")
	}
	return cmd()
}
