	for i := range runs {
		go func() {
			cmd := exec.Command("docker", "call", fmt.Sprint(i))
			_ = cmd.Run()
			done <- struct{}{}
		}()
	}
	for range runs {
		<-done
	}

	got := f.Invocations()
	if len(got) != runs {
		t.Fatalf("journal has %d entries, want %d", len(got), runs)
